// Werte werden als ein base64-kodierter JSON-Block an die Datenbank uebergeben (Befund Smoke-Test 21865).
const MUSTER = [
  [/(?:)\b(api[_-]?key|apikey|token|secret|password|passwort|pwd|authorization|bearer|credential|client[_-]?secret)\b\s*[:=]?\s*\S+/gi, "[entfernt]"],
  [/eyJ[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}/g, "[entfernt]"],
  [/(token|key|secret|password)=[^&\s]+/gi, "[entfernt]"],
  [/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, "[entfernt]"],
  [/postgres(?:ql)?:\/\/[^\s]+/gi, "[entfernt]"]
];
const TRANSIENT = [408, 425, 429, 500, 502, 503, 504];
function b64(o) {
  const s = JSON.stringify(o);
  return (typeof Buffer !== "undefined") ? Buffer.from(s, "utf8").toString("base64") : btoa(unescape(encodeURIComponent(s)));
}
const ergebnis = [];
for (const item of $input.all()) {
  const kontext = item.json.context_id;
  if (!/^[a-z][a-z0-9_]{2,63}$/.test(String(kontext || ""))) {
    throw new Error("error_handler_invalid_input: context_id fehlt oder hat kein gueltiges Format");
  }
  if (!item.json.error_id) {
    throw new Error("error_handler_invalid_input: error_id fehlt");
  }
  let text = String(item.json.error_message_raw || "");
  const rohNiedrig = text.toLowerCase();
  for (const paar of MUSTER) {
    text = text.replace(paar[0], paar[1]);
  }
  if (text.length > 500) {
    text = text.slice(0, 497) + "...";
  }
  const code = (item.json.status_code === undefined || item.json.status_code === null || item.json.status_code === "") ? null : Number(item.json.status_code);
  const versuch = Number(item.json.attempt) || 1;
  const maximal = Number(item.json.max_attempts) || 3;
  let klasse = "permanent";
  if (rohNiedrig.indexOf("append_only_violation") !== -1 ||
      rohNiedrig.indexOf("permission denied") !== -1 ||
      code === 401 || code === 403) {
    klasse = "security";
  } else if (rohNiedrig.indexOf("_chk") !== -1 ||
             rohNiedrig.indexOf("violates check constraint") !== -1 ||
             rohNiedrig.indexOf("schema") !== -1 ||
             rohNiedrig.indexOf("contract") !== -1) {
    klasse = "contract";
  } else if (code !== null && TRANSIENT.indexOf(code) !== -1) {
    klasse = "transient";
  }
  const wiederholbar = klasse === "transient" && versuch < maximal;
  let stufe = "log_only";
  if (klasse === "security") { stufe = "halt_and_notify"; }
  else if (klasse === "contract") { stufe = "notify"; }
  else if (klasse === "permanent") { stufe = "notify"; }
  else if (klasse === "transient" && !wiederholbar) { stufe = "notify"; }
  const status = wiederholbar ? "retry_scheduled" : "open";
  const zeile = {
    error_id: item.json.error_id,
    action_id: item.json.action_id || null,
    event_id: item.json.event_id || null,
    error_class: klasse,
    escalation_level: stufe,
    attempt: versuch,
    resolution_status: status,
    body: { status_code: code, attempt: versuch, max_attempts: maximal, message_safe: text }
  };
  ergebnis.push({ json: {
    context_id: kontext,
    error_id: zeile.error_id,
    action_id: zeile.action_id,
    error_class: klasse,
    escalation_level: stufe,
    retry_allowed: wiederholbar,
    next_attempt_delay_s: wiederholbar ? 30 * Math.pow(2, versuch - 1) : null,
    attempt: versuch,
    resolution_status: status,
    message_safe: text,
    trace_id: item.json.trace_id || null,
    row_b64: b64(zeile)
  } });
}
return ergebnis;

// Gibt die Eskalationsentscheidung an den Aufrufer zurueck, nicht nur die Datenbankantwort.
const k = $('Fehler klassifizieren und bereinigen').first().json;
const r = $input.first().json;
return [{ json: {
  status: "error_recorded",
  error_id: r.error_id || k.error_id,
  error_class: k.error_class,
  escalation_level: k.escalation_level,
  retry_allowed: k.retry_allowed,
  next_attempt_delay_s: k.next_attempt_delay_s,
  attempt: k.attempt,
  resolution_status: k.resolution_status,
  message_safe: k.message_safe,
  context_id: k.context_id,
  trace_id: k.trace_id
} }];
